    17	 * Valid controls: shortText | longText | select | toggle | number | media
    18	 * Auto-inferred: string→shortText, boolean→toggle, number→number,
    19	 *                string-literal union→select
    20	 * Auto-skipped:  on* handler props, children (emits children:true instead)
    21	 * Fails loudly:  any untagged non-handler, non-children prop
    22	 */
    23	
    24	import { Project, SyntaxKind } from 'ts-morph';
    25	import { readdirSync, writeFileSync, readFileSync, mkdtempSync } from 'fs';
    26	import { join, basename, dirname } from 'path';
    27	import { fileURLToPath } from 'url';
    28	import { tmpdir } from 'os';
    29	import { execSync } from 'child_process';
    30	
    31	const __filename = fileURLToPath(import.meta.url);
    32	const __dirname = dirname(__filename);
    33	const ROOT = join(__dirname, '../../');
    34	const EXPERIENCES_DIR =
    35	  process.env.CF_EXPERIENCES_DIR ||
    36	  join(ROOT, 'overrides/app/components/contentful/experiences');
    37	const OUTPUT_FILE = join(EXPERIENCES_DIR, 'definitions.ts');
    38	const TSCONFIG = join(ROOT, 'tsconfig.json');
    39	
    40	const CHECK_MODE = process.argv.includes('--check');
    41	
    42	// Contentful variable shape keyed by @cf control name
    43	const CONTROL_MAP = {
    44	  shortText: { type: 'Text', defaultValue: '' },
    45	  longText: { type: 'Text', defaultValue: '' },
    46	  select: { type: 'Text', defaultValue: '' },
    47	  toggle: { type: 'Boolean', defaultValue: false },
    48	  number: { type: 'Number', defaultValue: 0 },
    49	  media: { type: 'Media', defaultValue: '' },
    50	};
    51	
    52	const VALID_CONTROLS = Object.keys(CONTROL_MAP).join(', ');
    53	
    54	// collectionHero → collection-hero
    55	function toKebab(str) {
    56	  return str.replace(/([A-Z])/g, (ch) => '-' + ch.toLowerCase()).replace(/^-/, '');
    57	}
    58	
    59	// collection-hero → Collection Hero
    60	function toTitleCase(kebab) {
    61	  return kebab
    62	    .split('-')
    63	    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    64	    .join(' ');
    65	}
    66	
    67	function inferControl(typeText) {
    68	  const clean = typeText.trim();
    69	  if (clean === 'string') return 'shortText';
    70	  if (clean === 'boolean') return 'toggle';
    71	  if (clean === 'number') return 'number';
    72	  // String literal union: "left" | "right"
    73	  if (/^"[^"]*"(\s*\|\s*"[^"]*")*$/.test(clean)) return 'select';
    74	  return null;
    75	}
    76	
    77	// Parse the text after "@cf " from a JSDoc inner text.
    78	// Returns { displayName, control?, defaultValue? } | null
    79	// Syntax: @cf DisplayName [, control [, defaultValue]]
    80	function parseCfComment(jsDocInnerText) {
    81	  const match = jsDocInnerText.match(/@cf\s+(.+?)(?:\s*[\n*]|$)/m);
    82	  if (!match) return null;
    83	  const parts = match[1].split(',').map((s) => s.trim());
    84	  if (parts.length === 1) return { displayName: parts[0] };
    85	  const result = { displayName: parts[0], control: parts[1] };
    86	  if (parts.length >= 3) result.defaultValue = parts[2];
    87	  return result;
    88	}
    89	
    90	function getCfTag(member) {
    91	  for (const jsDoc of member.getJsDocs()) {
    92	    const tag = parseCfComment(jsDoc.getInnerText());
    93	    if (tag) return tag;
    94	  }
    95	  return null;
    96	}
    97	
    98	function serializeValue(val) {
    99	  if (typeof val === 'string') return `'${val}'`;
   100	  return String(val);
   101	}
   102	
   103	function processFile(sourceFile, filePath) {
   104	  const fileName = basename(filePath, '.tsx');
   105	  const fullText = sourceFile.getFullText();
   106	
   107	  if (!fullText.includes('@cf-register')) return null;
   108	
   109	  const id = toKebab(fileName);
   110	  const name = toTitleCase(id);
