   121	  if (!propsType) {
   122	    throw new Error(`${filePath}: No Props type found (expected '${propsTypeName}')`);
   123	  }
   124	
   125	  const typeNode = propsType.getTypeNode();
   126	  if (!typeNode || !typeNode.isKind(SyntaxKind.TypeLiteral)) {
   127	    throw new Error(
   128	      `${filePath}: Props type must be a plain type literal { ... }. ` +
   129	        'Intersection types, mapped types, and imported shapes are not supported.',
   130	    );
   131	  }
   132	
   133	  const properties = typeNode.getProperties();
   134	  const variables = {};
   135	  let hasChildren = false;
   136	  const errors = [];
   137	
   138	  for (const member of properties) {
   139	    const propName = member.getName();
   140	
   141	    if (/^on[A-Z]/.test(propName)) continue;
   142	
   143	    if (propName === 'children') {
   144	      hasChildren = true;
   145	      continue;
   146	    }
   147	
   148	    const cfTag = getCfTag(member);
   149	
   150	    if (!cfTag) continue;
   151	
   152	    let control = cfTag.control ?? null;
   153	
   154	    if (!control) {
   155	      const propTypeNode = member.getTypeNode();
   156	      const typeText = propTypeNode?.getText() ?? '';
   157	      control = inferControl(typeText);
   158	      if (!control) {
   159	        errors.push(
   160	          `${filePath}:${member.getStartLineNumber()}: '${propName}' type '${typeText}' ` +
   161	            `cannot be inferred. Use: /** @cf ${cfTag.displayName}, <control> */ ` +
   162	            `Valid controls: ${VALID_CONTROLS}`,
   163	        );
   164	        continue;
   165	      }
   166	    }
   167	
   168	    const varDef = CONTROL_MAP[control];
   169	    if (!varDef) {
   170	      errors.push(
   171	        `${filePath}: Unknown control '${control}' on '${propName}'. ` +
   172	          `Valid controls: ${VALID_CONTROLS}`,
   173	      );
   174	      continue;
   175	    }
   176	
   177	    variables[propName] = {
   178	      type: varDef.type,
   179	      displayName: cfTag.displayName,
   180	      defaultValue: cfTag.defaultValue ?? varDef.defaultValue,
   181	    };
   182	  }
   183	
   184	  if (errors.length > 0) throw new AggregateError(errors, 'prop errors');
   185	
   186	  return { id, name, componentName, fileName, variables, hasChildren };
   187	}
   188	
   189	function generateOutput(components) {
   190	  const imports = components
   191	    .map(({ componentName, fileName }) => `import ${componentName} from './${fileName}';`)
   192	    .join('\n');
   193	
   194	  const entries = components.map(({ componentName, id, name, variables, hasChildren }) => {
   195	    const varLines = Object.entries(variables)
   196	      .map(
   197	        ([key, { type, displayName, defaultValue }]) =>
   198	          `        ${key}: { type: '${type}', displayName: ${JSON.stringify(displayName)}, defaultValue: ${serializeValue(defaultValue)} },`,
   199	      )
   200	      .join('\n');
   201	
   202	    const childrenLine = hasChildren ? '\n      children: true,' : '';
   203	
   204	    return `  {
   205	    component: ${componentName},
   206	    definition: {
   207	      id: '${id}',
   208	      name: ${JSON.stringify(name)},${childrenLine}
   209	      variables: {
   210	${varLines}
   211	      },
   212	    },
   213	  }`;
   214	  });
   215	
   216	  return (
   217	    `// AUTOGENERATED — do not edit. Source: ./*.tsx\n` +
   218	    `\n` +
   219	    `import { defineComponents } from '@contentful/experiences-sdk-react';\n` +
   220	    `${imports}\n` +
   221	    `\n` +
   222	    `defineComponents([\n` +
   223	    `${entries.join(',\n')}\n` +
   224	    `]);\n`
   225	  );
   226	}
   227	
   228	// ── Main ─────────────────────────────────────────────────────────────────────
   229	
   230	const project = new Project({ tsConfigFilePath: TSCONFIG, skipAddingFilesFromTsConfig: true });
   231	
   232	const sourceFiles = readdirSync(EXPERIENCES_DIR)
   233	  .filter((f) => f.endsWith('.tsx') && f !== 'definitions.ts')
   234	  .sort();
   235	
   236	const components = [];
   237	const errors = [];
   238	
   239	for (const file of sourceFiles) {
   240	  const filePath = join(EXPERIENCES_DIR, file);
   241	  const sourceFile = project.addSourceFileAtPath(filePath);
   242	
   243	  try {
   244	    const result = processFile(sourceFile, filePath);
   245	    if (result) components.push(result);
   246	  } catch (err) {
   247	    if (err instanceof AggregateError) {
   248	      errors.push(...err.errors);
   249	    } else {
   250	      errors.push(err.message);
   251	    }
   252	  }
   253	}
   254	
   255	if (errors.length > 0) {
   256	  console.error('\nContentful codegen failed:\n');
   257	  errors.forEach((e) => console.error('  ✗ ' + e));
   258	  process.exit(1);
   259	}
   260	
   261	if (components.length === 0) {
   262	  console.error(`No components with /** @cf-register */ found in ${EXPERIENCES_DIR}`);
   263	  process.exit(1);
   264	}
   265	
   266	const output = generateOutput(components);
   267	
   268	if (CHECK_MODE) {
   269	  const tmpDir = mkdtempSync(join(tmpdir(), 'cf-codegen-'));
   270	  const tmpFile = join(tmpDir, 'definitions.ts');
   271	  writeFileSync(tmpFile, output, 'utf-8');
   272	
   273	  try {
   274	    const existing = readFileSync(OUTPUT_FILE, 'utf-8');
   275	    if (existing === output) {
   276	      console.log('✓ definitions.ts is up to date');
   277	      process.exit(0);
   278	    } else {
   279	      console.error('✗ definitions.ts is out of date. Run: npm run generate:contentful');
   280	      process.exit(1);
   281	    }
   282	  } catch {
   283	    console.error('✗ definitions.ts does not exist. Run: npm run generate:contentful');
   284	    process.exit(1);
   285	  }
   286	}
   287	
   288	writeFileSync(OUTPUT_FILE, output, 'utf-8');
   289	console.log(
   290	  `✓ Generated definitions.ts (${components.length} component${components.length === 1 ? '' : 's'}): ` +
   291	    components.map((c) => c.componentName).join(', '),
   292	);

