===== getConfig.mjs (rest: write-gating + ENVIRONMENT_ID default) =====
  // .env update logic
  if (!existsSync(ENV_FILE)) {
    log.error('.env file not found at repo root. Create it from .env.sample first.');
    process.exit(1);
  }

  const raw = readFileSync(ENV_FILE, 'utf8');
  const entries = parseEnv(raw);
  const changes = [];

  function upsertVar(key, value) {
    if (SKIP_VARS.has(key)) return;
    const existing = entries.find((e) => e.type === 'var' && e.key === key);
    if (!existing) {
      entries.push({ type: 'var', key, value });
      changes.push({ action: 'add', key, value });
    } else if (!existing.value) {
      existing.value = value;
      changes.push({ action: 'fill', key, value });
    } else if (existing.value !== value) {
      existing.value = value;
      changes.push({ action: 'update', key, value });
    }
  }

  // Always ensure CONTENTFUL_SPACE_ID is correct
  upsertVar('CONTENTFUL_SPACE_ID', spaceId);

  // Populate tokens for the local dev environment
  const localEnvId = process.env.CONTENTFUL_ENVIRONMENT_ID || 'dev';
  const localTokens = tokenMap[localEnvId];
  if (localTokens) {
    upsertVar('CONTENTFUL_DELIVERY_TOKEN', localTokens.deliveryToken);
    upsertVar('CONTENTFUL_PREVIEW_TOKEN', localTokens.previewToken);
  } else {
    log.warn(`No API key found for environment '${localEnvId}'. Run setup:contentful first.`);
  }

  // Print the full token map for all environments (always shown, regardless of write access)
  log.section('Live token values per environment');
  for (const envId of ENVIRONMENT_IDS) {
    const tokens = tokenMap[envId];
    if (!tokens) {
      log.warn(`${envId}: no API key found (run setup:contentful)`);
    } else {
      console.log(`  ${envId.padEnd(10)} delivery: ${tokens.deliveryToken.slice(0, 8)}…  preview: ${tokens.previewToken ? tokens.previewToken.slice(0, 8) + '…' : '(none)'}`);
    }
  }

  if (changes.length === 0) {
    log.success('.env is already up to date.');
    return;
  }

  log.section('Changes');
  for (const c of changes) {
    const label = c.action === 'add' ? '+ add  ' : c.action === 'fill' ? '~ fill ' : '~ update';
    console.log(`  ${label}  ${c.key}`);
  }

  if (!canWrite) {
    log.warn(approved ? 'Dry-run — no writes made.' : 'Read-only — contact a tier-1-approver to apply these changes.');
    return;
  }

  writeFileSync(ENV_FILE, serializeEnv(entries), 'utf8');
  log.success(`.env updated (${changes.length} change${changes.length === 1 ? '' : 's'}).`);
}

main().catch((err) => {
  log.error(err.message ?? err);
  process.exit(1);
});

